// Auto-generated 128px data-URI mascots for the Android widget (react-native-android-widget
// cannot reliably resolve require()'d assets in a release build, so we inline base64 here).
// Regenerate with: sips -Z 128 <src>.png --out <tmp>.png && base64 -i <tmp>.png

export const MASCOT_DATA: Record<string, `data:image${string}`> = {
  happy: "data:image/png;base64,",
  neutral: "data:image/png;base64,",
  sad: "data:image/png;base64,",
  scared: "data:image/png;base64,",
};
